Similar error was reported as issue #3591 which has been fixed since commit e8081 (I've confirmed), but I am still seeing the similar error with following code using rev 52c42b:

``` js
'use strict';
/*eslint-disable no-console */
var Promise = require('bluebird');

function doSomething() {
    return Promise.resolve()
    .then(function () {
        var o = 1 + 2;
        return o;
    }, function (err) {
        console.log('err:', err);
        var o = 1 - 2;
        return o;
    });
}

doSomething()
.then(function (ans) {
    console.log('ans=%d', ans);
});
```

Here's the output:

```
test.js|11 col 9 error| Expected indentation of 12 space characters but found 8. (indent)
test.js|12 col 9 error| Expected indentation of 12 space characters but found 8. (indent)
test.js|13 col 9 error| Expected indentation of 12 space characters but found 8. (indent)
test.js|14 col 5 error| Expected indentation of 8 space characters but found 4. (indent)
```

My indent rule is `[2, 4]`
